const paths={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 1.4 1.4m10 10 1.4 1.4m0-12.8L17 7m-10 10-1.4 1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bank:'M4 5h16v15H4zM8 5V3h8v2M4 10h16M9 10v10',activity:'M3 12h4l3-8 4 16 3-8h4',quality:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7zm-4 9 3 3 5-6',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',back:'m14 6-6 6 6 6',external:'M14 3h7v7m-1-6-10 10M10 4H4v16h16v-6',check:'m5 12 4 4L20 5',phone:'M6 3h3l2 5-2 2a13 13 0 0 0 5 5l2-2 5 2v3c0 2-3 3-5 2C9 18 5 14 3 8 2 6 3 3 6 3',calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16m-11 5h2',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14m5-2 6 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-5h4l1 3 3 1 3 2v4l-3 2-1 3-3 3h-4l-1-3-3-1-3-2v-4l3-2 1-3z',copy:'M8 8h12v13H8zM16 8V3H3v13h5',pin:'M12 22s8-7 8-13A8 8 0 0 0 4 9c0 6 8 13 8 13m3-13a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',close:'m5 5 14 14M19 5 5 19',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',alert:'M12 3 2 21h20zM12 9v5m0 3v.1',note:'M5 3h14v18H5zM9 8h6m-6 4h6m-6 4h4',filter:'M3 5h18M6 12h12m-8 7h4',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-4 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0m-5 0h.1',instagram:'M7 3h10a4 4 0 0 1 4 4v10a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V7a4 4 0 0 1 4-4m9 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0m1-5h.1',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 6 5 12 0 18-5-6-5-12 0-18',plus:'M12 5v14M5 12h14'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.note}"/></svg>`;
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=x=>String(x??'').trim();
const known=x=>clean(x)&&!/^unknown$|^not verified$|^n\/a$|^none$/i.test(clean(x));
const show=(x,fallback='Not recorded')=>known(x)?e(x):fallback;
const url=x=>{try{const u=new URL(clean(x));return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}};
const formatDate=(x,short=false)=>{if(!x)return 'Not dated';const d=new Date(x.length===10?`${x}T12:00:00+01:00`:x);return Number.isNaN(+d)?x:new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Lagos',day:'numeric',month:short?'short':'long',...(!short||d.getUTCFullYear()!==new Date().getUTCFullYear()?{year:'numeric'}:{})}).format(d);};
const formatTime=x=>!x?'':new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Lagos',hour:'2-digit',minute:'2-digit'}).format(new Date(x));
const dateTimeLocal=x=>{const d=x?new Date(x):new Date();return new Date(+d+3600000).toISOString().slice(0,16);};
const toIso=x=>x?new Date(`${x}:00+01:00`).toISOString():'';
const stageNames={review:'To review',approved:'Approved for calls',followup:'Follow-up',booked:'Meeting booked',deferred:'Review later',disqualified:'Disqualified',closed:'Not interested',excluded:'Source exclusion'};
const outcomeNames={no_answer:'No answer',connected:'Connected · no booking',follow_up:'Follow-up agreed',meeting_booked:'Meeting / second call booked',not_interested:'Not interested',wrong_number:'Wrong number / contact issue'};
const researchNames={qualified:'Research-qualified',reserve:'Evidence incomplete',unverified:'Sources disagree',excluded:'Source exclusion'};
const eventNames={call_started:'Call session started',call_cancelled:'Call session cancelled',call_synced:'Wispr transcript retrieved',call_analyzed:'Call analysis drafted',approved:'Approved for calls',disqualified:'Disqualified',deferred:'Deferred for review',review_saved:'Verification saved',returned_to_review:'Returned to review',call_logged:'Call logged',call_material_saved:'Transcript / review saved',call_corrected:'Call corrected',note:'Note added',followup_set:'Follow-up scheduled',added_to_day:'Added to today',settings:'Daily targets changed',backup_restored:'Backup restored'};
let bankPage=0;
let wisprStatus=null,syncSessionId='',syncTimer=null,syncAttempts=0,syncPaused=true,syncBusy=false;
let storedSessionDrafts=[];try{storedSessionDrafts=JSON.parse(localStorage.getItem('bevamped-call-drafts-v1')||'[]');}catch{}
const sessionDrafts=new Map(Array.isArray(storedSessionDrafts)?storedSessionDrafts.filter(v=>Array.isArray(v)&&v.length===2&&typeof v[0]==='string'&&v[1]&&typeof v[1]==='object'):[]);
function saveSessionDrafts(){try{localStorage.setItem('bevamped-call-drafts-v1',JSON.stringify([...sessionDrafts]));}catch{}}
let enteredDesk=false;
let boot=null,view='today',queue='review',selected='',tab='research',search='',stageFilter='',cityFilter='',groupFilter='',researchFilter='',conflictFilter=false,busy=false,stale=false,mobileDetail=false;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let noteDrafts={};try{noteDrafts=JSON.parse(localStorage.getItem('bevamped-note-drafts-v1')||'{}');}catch{}
let draftCache={};try{draftCache=JSON.parse(localStorage.getItem('bevamped-drafts-v1')||'{}');}catch{}
const draftFor=lead=>draftCache[lead.id]||{...getState(lead).review};
function saveDraft(id,draft){draftCache[id]=draft;try{localStorage.setItem('bevamped-drafts-v1',JSON.stringify(draftCache));}catch{};const s=document.querySelector('[data-draft-status]');if(s)s.textContent='Draft kept in this browser';}
function clearDraft(id){delete draftCache[id];try{localStorage.setItem('bevamped-drafts-v1',JSON.stringify(draftCache));}catch{}}
function getState(lead){return boot.state.leadStates[lead.id]||{stage:lead.researchStatus==='excluded'?'excluded':'review',review:{portfolio:false,presence:false,contact:false,note:'',approvedAt:null},notes:[],followUpDate:'',nextAction:'',reason:''};}
const getLead=id=>boot.dataset.leads.find(l=>l.id===id);
const sourceName=id=>boot.dataset.sources.find(s=>s.id===id)?.label||id||'Source not labelled';
const sourceKind=id=>boot.dataset.sources.find(s=>s.id===id)?.kind||'';
const assessment=l=>l.researchStatus==='qualified'?(l.sourceIds?.some(id=>sourceKind(id).includes('checked'))?'Earlier checked research':'Imported AI-qualified'):(researchNames[l.researchStatus]||'Not assessed');
const locationLabel=l=>{if(l.conflicts?.some(c=>c.kind==='location_review'))return 'Location needs confirmation';let area=clean(l.area);const city=clean(l.city);if(city&&area.toLowerCase().startsWith(city.toLowerCase()))area=area.slice(city.length).replace(/^[\s—–\-·,:/]+/,'');return [city||'Location unconfirmed',area].filter(Boolean).join(' · ');};
const shortName=l=>l.name.replace(/\s*\([^)]*\)/g,'').trim();
const monogram=l=>shortName(l).split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const stageMarkup=s=>`<span class="stage ${e(s)}"><i class="stage-dot"></i>${e(stageNames[s]||s)}</span>`;
const evidenceKind=id=>sourceKind(id)==='importedAI'?'Imported AI claim':sourceKind(id).includes('checked')?'Earlier checked source':'Discovery source claim';
const differenceLabel=kind=>({interpretation:'Different opportunity hypotheses',research_disposition:'Source assessment disagreement',source_observation:'Different research observations',name_variant:'Name variants / incomplete name claims',activity_date_claim:'Dates reported by different sources',factual_claim:'Factual source difference',location_review:'Base location / service area needs confirmation'}[kind]||'Source claim to review');
function activityDates(l){
  const claims=(l.activityEvidence||[]).filter(a=>/^\d{4}-\d{2}-\d{2}$/.test(a.date||''));
  const dates=[...new Set([l.latestActivityDate,...claims.map(a=>a.date)].filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')))].sort().reverse();
  if(!dates.length)return 'Not dated<small>Check original activity evidence</small>';
  return dates.slice(0,3).map(date=>{const records=claims.filter(a=>a.date===date);const kinds=[...new Set(records.map(a=>evidenceKind(a.sourceId)))];return `<div class="activity-date-claim">${e(formatDate(date,true))}<small>${e(kinds.join(' · ')||'Retained source date')}</small></div>`;}).join('')+(dates.length>3?'<button class="text-link" data-action="tab" data-tab="sources">All dated sources</button>':'')+`<small>Source-rated confidence: ${show(l.activityConfidence,'Not stated')}</small>`;
}
function projectEvidence(l){
  const groups=new Map();
  for(const p of l.projects||[]){const u=url(p.url),key=u?u.replace(/\/\/$/,'/').replace(/^https?:\/\/(www\.)?/,'').replace(/\/$/,''):clean(p.name).toLowerCase();if(!groups.has(key))groups.set(key,{name:p.name,url:u,claims:[]});const g=groups.get(key);if(!g.claims.some(c=>c.note===p.note&&c.sourceId===p.sourceId))g.claims.push(p);}
  if(!groups.size)return '<p class="research-note">No attributable completed project examples were recorded. Check original work before approving.</p>';
  return [...groups.values()].map((p,i)=>`<div class="project-row"><span class="project-index">${String(i+1).padStart(2,'0')}</span><div><div class="project-title">${e((p.name||'Project reference').replace(/\s*(\||—|:)\s*https?:\/\/\S+/g,'').replace(/https?:\/\/\S+/g,''))}</div>${p.claims.map(c=>`<p class="project-note"><strong>${e(evidenceKind(c.sourceId))}.</strong> ${show(c.note,'Completion and attribution need checking.')}</p>`).join('')}${link(p.url,'Open project evidence')}</div></div>`).join('');
}
function link(href,label,ico='external',cls='evidence-link'){const u=url(href);return u?`<a class="${cls}" href="${e(u)}" target="_blank" rel="noopener noreferrer">${icon(ico)}${e(label)}</a>`:'';}
const button=(label,action,cls='',ico='',data='')=>`<button class="button ${cls}" data-action="${action}" ${data}>${ico?icon(ico):''}${e(label)}</button>`;
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`visible${error?' error':''}`;document.querySelector('#announcements').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',error?8000:3500);}
async function command(type,payload={},message='Saved to this computer'){
  if(busy)return false;busy=true;setBusy(true);
  try{const r=await fetch('/api/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:boot.state.revision,command:{type,payload}})});const data=await r.json();if(!r.ok){if(r.status===409)stale=true;throw new Error(data.error||'Could not save.');}boot=data;stale=false;if(message)toast(message);return true;}catch(err){toast(err.message,true);const errbox=modal.querySelector('[data-modal-error]');if(errbox)errbox.textContent=err.message;return false;}finally{busy=false;setBusy(false);}}
function setBusy(on){document.querySelectorAll('[data-save-action]').forEach(el=>{el.disabled=on;el.setAttribute('aria-busy',String(on));});}
async function reload(){try{const r=await fetch('/api/bootstrap');if(!r.ok)throw new Error('The local app is unavailable. Reopen it with the launcher.');boot=await r.json();stale=false;render();toast('Workspace refreshed. Unsaved drafts are still available.');}catch(err){toast(err.message,true);}}
function counts(){return boot.dataset.leads.reduce((a,l)=>{const s=getState(l).stage;a[s]=(a[s]||0)+1;return a;},{});}
function candidates(){
  const leads=boot.dataset.leads;
  let pool;
  if(view==='today'){
    const day=boot.state.days[boot.today]||{reviewQueue:[],callQueue:[]};
    if(queue==='review')pool=day.reviewQueue.map(getLead).filter(Boolean);
    else if(queue==='calls')pool=day.callQueue.map(getLead).filter(l=>l&&['approved','followup'].includes(getState(l).stage)&&(!getState(l).followUpDate||getState(l).followUpDate<=boot.today));
    else pool=leads.filter(l=>{const s=getState(l);return s.followUpDate&&s.followUpDate<=boot.today&&['followup','deferred','booked','approved'].includes(s.stage);}).sort((a,b)=>getState(a).followUpDate.localeCompare(getState(b).followUpDate));
  }else pool=[...leads].sort((a,b)=>{const ra=a.researchStatus==='qualified'?1:0,rb=b.researchStatus==='qualified'?1:0;return rb-ra||(b.score||0)-(a.score||0)||a.name.localeCompare(b.name);});
  return pool.filter(l=>{
    const s=getState(l),needle=search.toLowerCase();
    return (!needle||[l.name,...(l.aliases||[]),l.city,l.area,l.principal?.name,...(l.phones||[]).map(p=>p.number)].join(' ').toLowerCase().includes(needle))&&(!stageFilter||s.stage===stageFilter)&&(!cityFilter||l.city===cityFilter)&&(!groupFilter||l.presenceGroup===groupFilter)&&(!researchFilter||l.researchStatus===researchFilter)&&(!conflictFilter||l.conflicts?.some(c=>c.status!=='resolved')||l.identityReview?.status==='unresolved');
  });
}
function navItem(id,label,ico,count){return `<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${count!==undefined?`<b class="count">${count}</b>`:''}</button>`;}
function sidebar(){return `<aside class="sidebar" tabindex="0" aria-label="Workspace navigation"><button class="brand" data-action="nav" data-view="today" aria-label="BOLT by BEVAMPED, Today"><img src="/identity/bolt-lockup.svg" alt="BOLT"><span class="brand-sub">BY BEVAMPED</span></button><div class="nav-label">Your workspace</div><nav class="nav">${navItem('today','Today','sun')}${navItem('bank','Lead bank','bank',boot.dataset.leads.length)}${navItem('tasks','Tasks','check',(boot.state.tasks||[]).filter(t=>['open','waiting'].includes(t.status)).length)}${navItem('meetings','Meetings','calendar')}${navItem('weekly','Weekly review','activity')}${navItem('activity','Activity','activity',boot.state.calls.length)}${navItem('quality','Source review','quality')}</nav><div class="sidebar-note"><span class="sidebar-rule"></span><strong>Research first.<br>Make the call count.</strong><p>BEVAMPED Outreach<br>& Lead Tracker</p></div><div class="sidebar-bottom"><div class="storage-status">${icon('note')}Local data · revision ${boot.state.revision}</div><button class="sidebar-footer-btn" data-action="settings">${icon('settings')}<span>Targets & settings</span></button></div></aside>`;}
function metrics(){return dailyVisuals(boot); }
function row(l){const s=getState(l);const hint=l.identityReview?.status==='unresolved'?'Identity needs checking':l.conflicts?.some(c=>c.kind==='location_review')?'Location needs checking':l.conflicts?.length?`${l.conflicts.length} source difference${l.conflicts.length===1?'':'s'}`:l.researchStatus==='qualified'?assessment(l):'Needs your review';return `<button class="lead-row ${selected===l.id?'selected':''}" data-action="select" data-id="${e(l.id)}" ${selected===l.id?'aria-current="true"':''}><span class="lead-monogram">${e(monogram(l))}</span><span class="lead-row-body"><span class="lead-row-title">${e(shortName(l))}</span><span class="lead-row-sub">${e(locationLabel(l).split(';')[0])}</span><span class="lead-row-meta">${stageMarkup(s.stage)}<span class="source-hint">${e(hint)}</span></span></span>${icon(selected===l.id?'check':'chevron','row-chevron')}</button>`;}
function emptyQueue(){const isCall=queue==='calls';return `<div class="empty-state"><span class="empty-icon">${icon(isCall?'phone':queue==='followups'?'calendar':'check')}</span><h3>${isCall?'Your call list starts here.':queue==='followups'?'Nothing due today.':'No leads in this view.'}</h3><p>${isCall?'Personally approve a studio after reviewing its work and contact route. It will appear here.':queue==='followups'?'Scheduled follow-ups and deferred reviews will appear when their date arrives.':'Try another filter or choose leads from the bank.'}</p>${button(isCall?'Review today’s leads':'Explore the lead bank',isCall?'queue':'nav','',isCall?'check':'bank',isCall?'data-queue="review"':'data-view="bank"')}</div>`;}
function workspace(){const matches=candidates();bankPage=Math.max(0,Math.min(bankPage,Math.ceil(matches.length/20)-1));const list=view==='bank'?matches.slice(bankPage*20,bankPage*20+20):matches;if(!selected||!getLead(selected)||(!list.some(l=>l.id===selected)&&!mobileDetail))selected=list[0]?.id||'';const lead=getLead(selected);const title=view==='bank'?`${matches.length} ${matches.length===1?'studio':'studios'}`:queue==='review'?'Selected for today':queue==='calls'?'Personally approved':'Due for attention';return `<div class="workspace ${mobileDetail?'show-detail':''}"><section class="list-pane" aria-label="Lead list"><div class="list-heading"><strong>${title}</strong><span>${view==='today'&&queue==='review'?`${list.length} leads · stable daily selection`:view==='bank'?`${matches.length?bankPage*20+1:0}–${Math.min(bankPage*20+20,matches.length)} of ${matches.length}`:`${list.length} ${list.length===1?'lead':'leads'}`}</span></div><div class="lead-list">${list.length?list.map(row).join(''):emptyQueue()}</div>${view==='bank'&&matches.length>20?`<div class="list-pagination"><button class="button small" data-action="page" data-step="-1" ${bankPage===0?'disabled':''}>Previous</button><span>Page ${bankPage+1} of ${Math.ceil(matches.length/20)}</span><button class="button small" data-action="page" data-step="1" ${bankPage>=Math.ceil(matches.length/20)-1?'disabled':''}>Next</button></div>`:''}</section><div><button class="mobile-back" data-action="back-to-list">${icon('back')}Back to the list</button>${lead?inspector(lead):`<div class="no-selection">${icon('bank')}<h2>A clearer view of each studio.</h2><p>Select a lead to see its research, your checks and next steps.</p></div>`}</div></div>`;}
function callHeaderAction(l){const session=openSessions().find(s=>s.leadId===l.id);return session?`<div class="call-header-action">${button('Resume call','session-open','primary','phone',`data-id="${e(session.id)}"`)}</div>`:['approved','followup','booked'].includes(getState(l).stage)?`<div class="call-header-action">${button('Start call','start-call','primary','phone','data-save-action')}</div>`:tab!=='verification'?`<div class="call-header-action">${button('Review this studio','tab','primary','arrow','data-tab="verification"')}</div>`:'';}
function inspector(l){const s=getState(l);return `<article class="inspector" aria-label="${e(l.name)} lead details"><header class="inspector-head"><div class="inspector-overline"><span class="lead-id">${e(l.id)}</span>${stageMarkup(s.stage)}</div><h2>${e(l.name)}</h2><div class="lead-location">${icon('pin')}${e(locationLabel(l))}</div><p class="lead-description">${show(l.specialization,'Interior-design prospect. Read the source evidence before deciding whether the studio fits.')}</p><div class="external-links">${link(l.website,'Website','globe','button')}${link(l.instagram,'Instagram','instagram','button')}${link(l.bioLink,'Portfolio / bio','external','button')}</div>${callHeaderAction(l)}${whatsappLinks(l)}</header><div class="inspector-tabs" role="tablist" aria-label="Lead information">${[['research','Research'],['verification','Your verification'],['calls','Calls & notes'],['sources','Sources'+(l.conflicts?.length?' · '+l.conflicts.length:'')]].map(([id,label])=>`<button role="tab" tabindex="${tab===id?0:-1}" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-action="tab" data-tab="${id}" id="tab-${id}" aria-controls="lead-tab-panel">${e(label)}</button>`).join('')}</div><section class="inspector-body" id="lead-tab-panel" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='research'?research(l):tab==='verification'?verification(l):tab==='calls'?callsAndNotes(l):sources(l)}</section>${inspectorFooter(l)}</article>`;}
function research(l){const s=getState(l);const hasPhone=l.phones?.some(p=>known(p.number));return `${l.identityReview?.status==='unresolved'?`<div class="notice error">${icon('alert')}<p><strong>Studio identity needs confirmation.</strong> ${e(l.identityReview.reason)} Related record${l.identityReview.relatedLeadIds?.length===1?'':'s'}: ${e((l.identityReview.relatedLeadIds||[]).join(', '))}.</p></div>`:''}${l.conflicts?.some(c=>c.kind==='location_review')?`<div class="notice"><p><strong>Location needs confirmation.</strong> Source city: ${show(l.city)}. Source area / coverage: ${show(l.area)}. Confirm the base location and service area before relying on a city filter.</p></div>`:''}${l.conflicts?.some(c=>c.status!=='resolved')?`<div class="notice">${icon('alert')}<p><strong>The sources differ on this studio.</strong> Check the ${l.conflicts.length} recorded difference${l.conflicts.length===1?'':'s'} before approving. <button class="text-link" data-action="tab" data-tab="sources">Compare sources</button></p></div>`:''}${/CALL HOLD/i.test(l.manualVerificationNeeded||'')?`<div class="notice error">${icon('phone')}<p><strong>Contact route needs confirmation.</strong> ${e(l.manualVerificationNeeded)}</p></div>`:''}<h3 class="section-kicker">At a glance</h3><div class="fact-grid"><div><div class="fact-label">Principal / decision-maker</div><div class="fact-value">${show(l.principal?.name)}<small>${show(l.principal?.role,'Role not confirmed')}</small></div></div><div><div class="fact-label">Public business phone</div><div class="fact-value">${hasPhone?l.phones.filter(p=>known(p.number)).map(p=>`<div class="phone-line"><span>${e(p.number)}</span><button data-action="copy" data-value="${e(p.number)}" aria-label="Copy ${e(p.number)}">${icon('copy')}</button></div>`).join(''):'No number recorded'}<small>Public listing · not a tested number</small></div></div><div><div class="fact-label">Recorded activity</div><div class="fact-value">${activityDates(l)}</div></div><div><div class="fact-label">Research assessment</div><div class="fact-value">${e(assessment(l))}<small>AI/source assessment · not your approval</small></div></div></div><hr class="divider"><h3 class="section-kicker">Project evidence</h3>${projectEvidence(l)}<p class="evidence-caption">These are retained research claims. Your personal confirmation belongs in the next tab.</p><hr class="divider"><h3 class="section-kicker">What to look at</h3><p class="research-note">${show(l.websiteObservation,'No website observation recorded.')}</p>${known(l.opportunity)?`<p class="research-note"><strong>Possible opportunity.</strong> ${e(l.opportunity)}</p>`:''}${known(l.timingSignal)?`<p class="research-note"><strong>Timing.</strong> ${e(l.timingSignal)}</p>`:''}${known(l.manualVerificationNeeded)?`<p class="evidence-caption"><strong>Open checks:</strong> ${e(l.manualVerificationNeeded)}</p>`:''}${known(l.email)?`<p class="evidence-caption">Business contact: ${e(l.email)}</p>`:''}${s.reason?`<hr class="divider"><p class="research-note"><strong>Your decision note:</strong> ${e(s.reason)}</p>`:''}`;}
function verification(l){const s=getState(l),d=draftFor(l);return `<p class="review-intro">Check the original work, confirm the fit, and decide for yourself. Imported scores never approve a lead.</p>${s.review.approvedAt?`<div class="notice success">${icon('check')}<p>You approved this studio on ${e(formatDate(s.review.approvedAt,true))}. You can update your notes. <button class="text-link" data-action="return-review">Return to review</button></p></div>`:''}<form id="review-form" data-lead="${e(l.id)}"><label class="check-item"><input type="checkbox" name="portfolio" ${d.portfolio?'checked':''}><span><strong>The work and studio fit what I’m looking for</strong><span>I checked the portfolio, attribution and relevant completed work.</span></span></label><label class="check-item"><input type="checkbox" name="presence" ${d.presence?'checked':''}><span><strong>I’ve checked the website and social presence</strong><span>I understand the studio and have a specific, honest reason to consider calling.</span></span></label><label class="check-item"><input type="checkbox" name="contact" ${d.contact?'checked':''}><span><strong>The business contact route looks suitable</strong><span>I checked the identity and public business number, including any source conflict.</span></span></label><label class="form-field">My findings<textarea name="note" placeholder="What did you notice? What fits, what is missing, and what would you want to understand on a call?">${e(d.note||'')}</textarea><span class="field-help">Write your own confirmation here. Research remains unchanged alongside it.</span></label><div class="form-actions"><span class="draft-status" data-draft-status>${draftCache[l.id]?'Draft kept in this browser':'Your observations, in your words'}</span><button class="button" data-action="save-review" data-save-action type="button">${icon('check')}Save observations</button></div></form>${s.followUpDate?`<p class="evidence-caption">Next attention: ${e(formatDate(s.followUpDate))}. ${e(s.nextAction||'')}</p>`:''}`;}
function callsAndNotes(l){const s=getState(l),calls=boot.state.calls.filter(c=>c.leadId===l.id).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt));return `<h3 class="section-kicker">Call history</h3><p class="field-help">Use Start call to keep the selected lead and Wispr transcript together. You can also log an outcome manually and attach notes later.</p>${calls.length?calls.map(c=>`<div class="history-item" id="call-${e(c.id)}"><div class="history-top"><span class="history-title">${e(outcomeNames[c.outcome]||c.outcome)}</span><div class="call-actions"><button class="text-link" data-action="call-material" data-id="${e(c.id)}">Transcript & review</button><button class="text-link" data-action="edit-call" data-id="${e(c.id)}">Correct log</button></div></div><div class="history-time">${e(formatDate(c.occurredAt,true))} · ${e(formatTime(c.occurredAt))} WAT</div>${c.notes?`<p>${e(c.notes)}</p>`:''}${c.meetingAt?`<div class="history-outcome">${icon('calendar')} ${e(formatDate(c.meetingAt,true))} · ${e(formatTime(c.meetingAt))} WAT</div>`:''}${c.followUpDate?`<div class="history-time">Follow-up ${e(formatDate(c.followUpDate,true))}</div>`:''}${workflowCallActions(c)}${calendarCallAction(c)}${callMaterialMarkup(c,{e,link})}</div>`).join(''):'<p class="research-note">No calls logged. Make the WhatsApp call separately, then log its outcome here.</p>'}<hr class="divider"><div class="history-top"><h3 class="section-kicker">My notes</h3><button class="text-link" data-action="followup">Set next action</button></div>${s.review.note?`<div class="note-item"><time>Personal verification</time><p>${e(s.review.note)}</p></div>`:''}${(s.notes||[]).slice().reverse().map(n=>`<div class="note-item"><time>${e(formatDate(n.createdAt,true))} · ${e(formatTime(n.createdAt))}</time><p>${e(n.text)}</p></div>`).join('')}<form id="note-form"><label class="form-field">Add a note<textarea name="note" placeholder="A research finding, a detail to remember, or context for the next conversation…">${e(noteDrafts[l.id]||'')}</textarea></label><div class="form-actions"><span class="field-help">Draft stays in this browser until you add the note</span><button class="button" data-action="add-note" data-save-action type="button">Add note</button></div></form>${s.followUpDate?`<p class="evidence-caption">Next: ${e(formatDate(s.followUpDate))} · ${e(s.nextAction||'Follow up')}</p>`:''}${workflowLead(l,boot)}${l.importedHistory?.length?`<hr class="divider"><h3 class="section-kicker">Imported history</h3><pre class="source-raw">${e(JSON.stringify(l.importedHistory,null,2))}</pre>`:''}`;}
function sources(l){return `<div class="notice">${icon('quality')}<p>These files contain source claims and earlier research. Repeated spreadsheet views are retained for traceability; they are not independent confirmations.</p></div>${l.conflicts?.length?`<h3 class="section-kicker">Source differences</h3>${l.conflicts.map(c=>`<div class="conflict-item"><strong>${e(c.field.replace(/([A-Z])/g,' $1'))}</strong><div class="source-type">${e(differenceLabel(c.kind))}</div><ul>${(c.values||[]).map(v=>`<li>${e(typeof v.value==='string'?v.value:JSON.stringify(v.value))}<br><small>${e(sourceName(v.sourceId))} · ${e(v.note||'')}</small></li>`).join('')}</ul><p>${show(c.resolution,'Requires your confirmation.')}</p></div>`).join('')}<hr class="divider">`:''}<h3 class="section-kicker">Retained evidence</h3>${(l.activityEvidence||[]).map(a=>`<div class="source-block"><h4>${a.date?e(formatDate(a.date,true)):'Undated activity'}</h4><p>${e(evidenceKind(a.sourceId))} · ${e(sourceName(a.sourceId))}</p><p>${show(a.note)}</p>${link(a.url,'Open activity source')}</div>`).join('')}${l.principal?.sourceUrl?`<div class="source-block"><h4>Principal attribution</h4>${link(l.principal.sourceUrl,'Open principal source')}</div>`:''}${(l.phones||[]).map(p=>`<div class="source-block"><h4>Phone · ${e(p.number)}</h4><p>Public source claim, untested</p>${link(p.url,'Open phone source')}</div>`).join('')}<hr class="divider"><h3 class="section-kicker">Source files</h3>${(l.sourceIds||[]).map(id=>`<div class="source-block"><h4>${e(sourceName(id))}</h4><p>${sourceKind(id)==='importedAI'?'Imported AI research · not newly verified':sourceKind(id).includes('checked')?'Earlier research with retained source checks':'Discovery / source material'}${(l.aliases||[]).length?' · aliases retained':''}</p></div>`).join('')}${(l.mergeNotes||[]).map(n=>`<p class="evidence-caption">${e(n)}</p>`).join('')}<details><summary class="details-toggle">Original source rows (${l.sourceRecords?.length||0})</summary>${(l.sourceRecords||[]).map(r=>`<div class="source-block"><h4>${e(sourceName(r.sourceId))}</h4><p>${e(r.sheet||'Record')} · row ${e(r.row||'')}</p><pre class="source-raw">${e(JSON.stringify(r.raw,null,2))}</pre></div>`).join('')}</details>${Number.isFinite(l.score)?`<details><summary class="details-toggle">Source-reported score · ${l.score}/100</summary><p class="quality-note">Scores came from research sources and may use different methods. They are not a purchase forecast or your approval.</p><p class="research-note">${show(l.scoreNotes)}</p></details>`:''}`;}
function inspectorFooter(l){const s=getState(l),session=openSessions().find(c=>c.leadId===l.id);let primary;if(session)primary=button('Resume call','session-open','primary','phone',`data-id="${e(session.id)}"`);else if(['approved','followup','booked'].includes(s.stage))primary=button('Start call','start-call','primary','phone','data-save-action');else if(tab==='verification')primary=button('Approve for calls','approve','primary','check','data-save-action');else primary=button('Review this studio','tab','primary','arrow','data-tab="verification"');return `<footer class="inspector-footer"><div class="footer-secondary">${['disqualified','closed','excluded','deferred'].includes(s.stage)?button('Return to review','return-review','small'):button('Not a fit','stage-dialog','small danger','','data-stage="disqualified"')}${['approved','followup','booked'].includes(s.stage)?button('Log manually','log-call','small'):['review'].includes(s.stage)?button('Later','stage-dialog','small','','data-stage="deferred"'):''}</div>${primary}</footer>`;}
function dailyView(){const day=boot.state.days[boot.today]||{reviewQueue:[],callQueue:[]};const callCount=day.callQueue.filter(id=>{const l=getLead(id);return l&&['approved','followup'].includes(getState(l).stage)&&(!getState(l).followUpDate||getState(l).followUpDate<=boot.today);}).length;const due=boot.dataset.leads.filter(l=>{const s=getState(l);return s.followUpDate&&s.followUpDate<=boot.today&&['followup','deferred','booked','approved'].includes(s.stage);}).length;return `<div class="page-heading today-heading"><div><p class="eyebrow">One lead at a time</p><h1>Today<span class="brand-accent">.</span></h1><p>Your research, your judgement, your next conversation.</p></div></div>${metrics()}${calendarAgenda(boot)}${workflowToday(boot)}${sessionStrip()}<div class="queue-heading"><div><h2>Your next steps</h2><p>Review the evidence. Decide who is ready for a call.</p></div><div class="queue-actions"><button class="button text replay-welcome" data-action="opening-prayer">Opening prayer ↗</button><button class="button text motion-control" data-action="toggle-motion" data-motion-toggle>Pause background motion</button></div></div><div class="workspace-tools"><div class="segments" aria-label="Daily queues">${[['review','To review',day.reviewQueue.length],['calls','Ready to call',callCount],['followups','Follow-ups',due]].map(([id,label,n])=>`<button data-action="queue" data-queue="${id}" class="${queue===id?'active':''}" aria-pressed="${queue===id}">${label}<span class="badge-count">${n}</span></button>`).join('')}</div>${button('Choose from bank','nav','small','plus','data-view="bank"')}</div>${workspace()}<p class="bottom-caption">Only your approval moves a lead into calls. Every saved decision stays in its history.</p>`;}
function filters(){return `<div class="bank-controls"><div class="search-box">${icon('search')}<input id="lead-search" type="search" placeholder="Search studios, people, cities…" value="${e(search)}" aria-label="Search the lead bank"></div><select class="filter-select" id="stage-filter" aria-label="Your stage"><option value="">All your stages</option>${Object.entries(stageNames).map(([v,n])=>`<option value="${v}" ${stageFilter===v?'selected':''}>${n}</option>`).join('')}</select><select class="filter-select" id="city-filter" aria-label="City"><option value="">All cities</option>${[...new Set(boot.dataset.leads.map(l=>l.city).filter(Boolean))].sort().map(c=>`<option ${cityFilter===c?'selected':''}>${e(c)}</option>`).join('')}</select><select class="filter-select" id="group-filter" aria-label="Digital presence"><option value="">All presence types</option>${[['B','B · Website'],['A','A · Substitute link'],['C','C · No verified site']].map(([v,n])=>`<option value="${v}" ${groupFilter===v?'selected':''}>${n}</option>`).join('')}</select><select class="filter-select" id="research-filter" aria-label="Research assessment"><option value="">All source assessments</option>${Object.entries(researchNames).map(([v,n])=>`<option value="${v}" ${researchFilter===v?'selected':''}>${n}</option>`).join('')}</select></div>`;}
function bankView(){return `<div class="page-heading"><div><p class="eyebrow">One central lead bank</p><h1>The lead bank.</h1><p>${boot.dataset.leads.length} retained company records, with source evidence and your decisions alongside.</p></div>${button('Export bank','export-menu','','download')}</div>${filters()}${conflictFilter?'<p class="tools-caption">Showing source differences. <button class="text-link" data-action="clear-conflicts">Show all studios</button></p>':''}${selected&&mobileDetail?button('Add to today’s review','add-review','small','plus'):''}${workspace()}<p class="bottom-caption">Source exclusions remain visible. You can return a studio to review if your own findings support it.</p>`;}
function activityView(){const events=[...boot.state.events].filter(v=>v.type!=='settings'||Object.keys(v.detail||{}).length).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `<div class="page-heading"><div><p class="eyebrow">Your working history</p><h1>Your activity.</h1><p>Decisions, calls, notes and next steps. Recorded when you save them.</p></div>${button('Export history','export-menu','','download')}</div>${metrics()}${events.length?`<div class="activity-table"><div class="activity-row activity-header"><div>When</div><div>Studio</div><div>What happened</div><div></div></div>${events.slice(0,250).map(v=>{const l=getLead(v.leadId),c=boot.state.calls.find(c=>c.id===v.detail?.callId);const note=v.detail?.reason||v.detail?.note||v.detail?.text||c?.notes||'';return `<div class="activity-row"><div class="date">${e(formatDate(v.createdAt,true))}<br>${e(formatTime(v.createdAt))}</div><div><strong>${l?e(shortName(l)):'Workspace'}</strong>${l?`<p>${e(l.city)}</p>`:''}</div><div>${e(eventNames[v.type]||v.type)}${c?`<p>${e(outcomeNames[c.outcome])}${c.meetingAt?' · '+e(formatDate(c.meetingAt,true))+' '+e(formatTime(c.meetingAt)):''}</p>`:''}${note?`<p>${e(note)}</p>`:''}</div><div>${l?`<button class="text-link" data-action="open-activity-lead" data-id="${e(l.id)}">Open lead</button>`:''}</div></div>`;}).join('')}</div>`:`<div class="wide-callout"><div><h3>Your history starts with the first decision.</h3><p>Nothing has been marked reviewed or called on your behalf.</p></div>${button('Start reviewing','nav','primary','arrow','data-view="today"')}</div>`}`;}
function qualityView(){const leads=boot.dataset.leads;const conflict=leads.filter(l=>l.conflicts?.some(c=>c.status!=='resolved')||l.identityReview?.status==='unresolved');const n=leads.length;const groups=Object.entries(researchNames).map(([key,label])=>({label,count:leads.filter(l=>l.researchStatus===key).length}));const cityCounts=Object.entries(leads.reduce((a,l)=>(a[l.city||'Unconfirmed']=(a[l.city||'Unconfirmed']||0)+1,a),{})).sort((a,b)=>b[1]-a[1]);return `<div class="page-heading"><div><p class="eyebrow">Understand the research</p><h1>The source evidence.</h1><p>Imported research is a starting point. Your own inspection decides who gets called.</p></div>${button('Export all evidence','export-menu','','download')}</div><div class="quality-grid"><section class="quality-summary"><h3 class="section-kicker">Source assessment · ${n} companies</h3>${groups.map(g=>`<div class="quality-bar-row"><span>${g.label}</span><div class="quality-bar"><div class="quality-fill" data-progress="${g.count/n*100}"></div></div><strong>${g.count}</strong></div>`).join('')}<p class="quality-note">“Research-qualified” is a source assessment. It does not mean personally checked, contact-ready or interested in a website. Scores across AI sources are not directly comparable.</p></section><section class="quality-summary"><h3 class="section-kicker">Location coverage</h3>${cityCounts.slice(0,8).map(([label,count])=>`<div class="quality-bar-row"><span>${e(label)}</span><div class="quality-bar"><div class="quality-fill" data-progress="${count/n*100}"></div></div><strong>${count}</strong></div>`).join('')}<p class="quality-note">Locations reflect retained source records. Unconfirmed locations stay visible and require checking.</p></section></div><div class="wide-callout"><div><h3>${conflict.length} studios have source differences.</h3><p>Compare conflicting phone, identity, website or qualification claims before making your decision.</p></div>${button('Review differences','view-conflicts','primary','quality')}</div><h3 class="section-kicker">The source collection</h3>${boot.dataset.sources.map(s=>`<div class="source-block"><h4>${e(s.label)}</h4><p>${s.kind==='importedAI'?'Supplied AI consolidation':s.kind.includes('checked')?'Earlier research with retained checks':'Source discovery / reference'} · raw rows preserved</p></div>`).join('')}<p class="quality-note">Original files were preserved. Derivative spreadsheet tabs and repeated exports were consolidated into company records. The backup export retains the full bank, conflicts, original rows and your saved history.</p>`;}
function render(){if(!boot)return;const names={today:'Today',bank:'Lead bank',activity:'Activity',quality:'Source review',tasks:'Tasks',meetings:'Meetings',weekly:'Weekly review'};app.innerHTML=`<div class="shell">${sidebar()}<main class="main" id="main"><div class="desk-atmosphere" aria-hidden="true">${meetingMark()}</div><header class="topbar"><div class="crumb"><span class="desk-label">Your desk</span><span class="slash">/</span><span>${names[view]}</span><span class="desk-date">${e(formatDate(boot.today,true))}</span></div><div class="topbar-actions"><button class="button theme-toggle" data-action="toggle-theme" data-theme-toggle>Dark mode</button><button class="button header-export" data-action="export-menu">${icon('download')}Export & backup</button></div></header>${stale?`<div class="save-warning"><span>A newer change was saved in another tab. Your current draft is safe.</span><button class="text-link" data-action="refresh">Refresh workspace</button></div>`:''}${view==='today'?dailyView():view==='bank'?bankView():view==='activity'?activityView():['tasks','meetings','weekly'].includes(view)?workflowPage(boot,view):qualityView()}</main></div>`;for(const el of app.querySelectorAll('[data-progress]'))el.style.width=`${Number(el.dataset.progress)}%`;bindInputs();window.BoltAppearance.sync();}
function bindInputs(){const noteForm=document.querySelector('#note-form');if(noteForm)noteForm.addEventListener('input',()=>{noteDrafts[selected]=noteForm.elements.note.value;try{localStorage.setItem('bevamped-note-drafts-v1',JSON.stringify(noteDrafts));}catch{}});const f=document.querySelector('#review-form');if(f)f.addEventListener('input',()=>saveDraft(f.dataset.lead,readReview()));const input=document.querySelector('#lead-search');if(input)input.addEventListener('input',()=>{const pos=input.selectionStart;search=input.value;bankPage=0;selected='';mobileDetail=false;render();const n=document.querySelector('#lead-search');n.focus();n.setSelectionRange(pos,pos);});for(const [id,assign] of [['stage-filter',v=>stageFilter=v],['city-filter',v=>cityFilter=v],['group-filter',v=>groupFilter=v],['research-filter',v=>researchFilter=v]])document.getElementById(id)?.addEventListener('change',ev=>{assign(ev.target.value);bankPage=0;selected='';mobileDetail=false;render();});}
function readReview(){const f=document.querySelector('#review-form');if(!f)return draftFor(getLead(selected));return {portfolio:f.elements.portfolio.checked,presence:f.elements.presence.checked,contact:f.elements.contact.checked,note:f.elements.note.value};}
function navigate(next){view=next;bankPage=0;selected='';mobileDetail=false;search='';stageFilter='';cityFilter='';groupFilter='';researchFilter='';conflictFilter=false;render();window.scrollTo({top:0,behavior:'instant'});}
function dialog(title,subtitle,content,onSubmit){modal.classList.remove('session-review');modal.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${e(title)}</h2><p>${e(subtitle)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body"><form id="modal-form">${content}<div class="inline-error" data-modal-error role="alert"></div><div class="modal-footer">${button('Cancel','close-modal')}<button class="button primary" type="submit" data-save-action>Save</button></div></form></div>`;modal.querySelectorAll('button:not([type])').forEach(b=>b.type='button');modal.showModal();modal.querySelector('#modal-form').addEventListener('submit',async ev=>{ev.preventDefault();await onSubmit(new FormData(ev.target));});}
function stageDialog(stage){const l=getLead(selected);const deferred=stage==='deferred';dialog(deferred?'Review this studio later':'Not the right fit',l.name,`<label class="form-field">${deferred?'Why are you deferring it?':'What did you find?'}<textarea name="reason" required placeholder="Keep the reason specific so you can understand your decision later."></textarea></label>${deferred?'<label class="form-field">Review again on<input name="followUpDate" type="date" required></label>':''}<p class="field-help">This keeps the lead and its evidence. You can return it to review.</p>`,async f=>{if(await command('set_stage',{leadId:l.id,stage,reason:f.get('reason'),followUpDate:f.get('followUpDate')||''},deferred?'Deferred with a review date':'Decision saved · lead kept in the bank')){modal.close();render();}});}
function callDialog(callId){const l=getLead(selected),c=boot.state.calls.find(c=>c.id===callId);dialog(c?'Correct a call log':'Log a call',`${shortName(l)} · all times are West Africa Time`,`${l.phones?.length?`<div class="notice">${icon('phone')}<p>${e(l.phones.map(p=>p.number).join(' · '))}</p></div>`:''}<label class="form-field">Outcome<select name="outcome" id="call-outcome" required><option value="">Choose what happened</option>${Object.entries(outcomeNames).map(([key,label])=>`<option value="${key}" ${c?.outcome===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="form-field">Call date and time<input name="occurredAt" type="datetime-local" value="${e(dateTimeLocal(c?.occurredAt))}" required></label><div id="meeting-field" ${c?.outcome==='meeting_booked'?'':'hidden'}><label class="form-field">Booked meeting / second call<input name="meetingAt" type="datetime-local" value="${c?.meetingAt?e(dateTimeLocal(c.meetingAt)):''}"></label></div><label class="form-field">What was said?<textarea name="notes" placeholder="Their exact words, the need discussed, or the reason for the outcome…">${e(c?.notes||'')}</textarea></label><div class="form-row"><label class="form-field">Follow-up date<input name="followUpDate" type="date" value="${e(c?.followUpDate||'')}"></label><label class="form-field">Next action<input name="nextAction" placeholder="What happens next?" value="${e(c?.nextAction||'')}"></label></div><p class="field-help">This logs an outcome; it does not record audio or place a WhatsApp call. A booking counts only with an agreed date and time. After saving a booking, review its calendar details to add your reminders. No invitation is sent to the prospect.</p>`,async f=>{let occurredAt,meetingAt;try{occurredAt=toIso(f.get('occurredAt'));meetingAt=toIso(f.get('meetingAt'));}catch{modal.querySelector('[data-modal-error]').textContent='Choose valid dates and times.';return;}if(await command(c?'edit_call':'log_call',{leadId:l.id,callId:c?.id,outcome:f.get('outcome'),occurredAt,meetingAt,notes:f.get('notes'),followUpDate:f.get('followUpDate'),nextAction:f.get('nextAction')},c?'Call correction saved':'Call logged')){modal.close();tab='calls';render();if(f.get('outcome')==='meeting_booked'){const saved=c?boot.state.calls.find(x=>x.id===c.id):boot.state.calls.at(-1);if(saved)await openCalendar(saved.id);}}});const outcome=modal.querySelector('#call-outcome');outcome.addEventListener('change',()=>{const meeting=outcome.value==='meeting_booked';modal.querySelector('#meeting-field').hidden=!meeting;modal.querySelector('[name="meetingAt"]').required=meeting;modal.querySelector('[name="followUpDate"]').required=outcome.value==='follow_up';});}
function callMaterialDialog(callId){const l=getLead(selected),c=boot.state.calls.find(c=>c.id===callId&&c.leadId===l.id);if(!c)return;dialog('Transcript & call review',`${shortName(l)} · ${formatDate(c.occurredAt,true)} ${formatTime(c.occurredAt)} WAT`,callMaterialFields(c,e),async f=>{const values=Object.fromEntries(['provider','notesUrl','transcript','summary','coaching'].map(key=>[key,f.get(key)||'']));if(await command('save_call_material',{leadId:l.id,callId:c.id,...values},'Call transcript and review saved locally')){modal.close();tab='calls';render();}});}
function settingsDialog(){const s=boot.state.settings;dialog('Set your working rhythm','Targets guide the day. You always decide when to stop.',`<div class="form-row"><label class="form-field">Daily review target<input name="reviewTarget" type="number" min="1" max="50" value="${s.reviewTarget}" required></label><label class="form-field">Usual call limit<input name="callLimit" type="number" min="1" max="100" value="${s.callLimit}" required></label></div><label class="form-field">Booked calls / meetings goal<input name="bookingTarget" type="number" min="1" max="30" value="${s.bookingTarget}" required></label><p class="quality-note">Meet the booking goal early and the day is complete. Reach the call limit first and the desk will show that clearly, with the decision to continue left to you.</p><hr class="divider">${connectionMarkup()}<hr class="divider">${calendarSettingsMarkup()}<hr class="divider"><h3 class="section-kicker">Your data stays here</h3><p class="field-help">Changes are saved to local files, with a backup before each save. Export a full backup to keep a separate copy.</p><div class="external-links"><a class="button small" href="/api/export?format=backup" download>${icon('download')}Full backup</a><a class="button small" href="/api/export?format=csv" download>${icon('download')}CSV bank</a><button class="button small" data-action="restore">Restore backup</button></div>`,async f=>{if(await command('settings',{reviewTarget:Number(f.get('reviewTarget')),callLimit:Number(f.get('callLimit')),bookingTarget:Number(f.get('bookingTarget'))},'Daily targets saved')){modal.close();render();}});refreshWisprStatus();}
function exportDialog(){dialog('Keep a copy of your work','Choose a portable bank or a complete restorable workspace.',`<div class="source-block"><h4>Lead bank · CSV</h4><p>Company details, your stage, verification notes, call totals, follow-ups and source detail.</p><a class="button small" href="/api/export?format=csv" download>${icon('download')}Download CSV</a></div><div class="source-block"><h4>Full workspace · JSON backup</h4><p>All research, original source rows, conflicts, personal decisions, exact call history and daily queues. Use this file to restore this same bank.</p><a class="button small" href="/api/export?format=backup" download>${icon('download')}Download full backup</a></div>`,async()=>modal.close());modal.querySelector('.modal-footer [type="submit"]').textContent='Done';}
function followupDialog(){const l=getLead(selected),s=getState(l);dialog('Set the next step',l.name,`<label class="form-field">Date<input name="date" type="date" value="${e(s.followUpDate||'')}" required></label><label class="form-field">Next action<textarea name="action" placeholder="What should you do when this date arrives?">${e(s.nextAction||'')}</textarea></label>`,async f=>{if(await command('followup',{leadId:l.id,followUpDate:f.get('date'),nextAction:f.get('action')},'Next step saved')){modal.close();render();}});}
function restoreDialog(){modal.close();dialog('Restore a saved workspace','Your current state will be backed up before it is replaced.',`<div class="notice">${icon('alert')}<p>Choose a full backup from this same lead bank. This replaces your current decisions and call history with the contents of the file.</p></div><label class="form-field">Full backup file<input id="backup-file" type="file" accept=".json,application/json" required></label>`,async()=>{const file=modal.querySelector('#backup-file').files[0];if(!file)return;try{const backup=JSON.parse(await file.text());const r=await fetch('/api/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:boot.state.revision,backup})});const data=await r.json();if(!r.ok)throw new Error(data.error);boot=data;modal.close();render();toast('Workspace restored. Previous state kept in local backups.');}catch(err){modal.querySelector('[data-modal-error]').textContent=err.message;}});}
async function wisprRequest(path,payload){
  const response=await fetch(`/api/wispr/${path}`,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
  let data;try{data=await response.json();}catch{throw new Error('The local server could not return a usable response. Refresh the desk and try again.');}
  if(!response.ok)throw new Error(data.error||'Wispr could not complete this request. Try again.');
  if(data.state&&data.dataset){boot=data;stale=false;render();}
  return data;
}
const openSessions=()=>boot?.state.callSessions?.filter(s=>!['completed','cancelled'].includes(s.status))||[];
const getSession=id=>boot.state.callSessions?.find(s=>s.id===id);
function sessionStrip(){const sessions=openSessions();return sessions.length?`<section class="session-strip" aria-label="Unfinished calls">${sessions.map(s=>`<div class="session-strip-row"><div>${icon('phone')}<span><strong>${e(getLead(s.leadId)?.name||'Call session')}</strong><small>${s.status==='active'?'Started '+e(formatTime(s.startedAt))+' WAT · record in Wispr separately':s.status==='waiting'?'Waiting for transcript · call not logged yet':'Transcript ready · your review is needed'}</small></span></div>${button(s.status==='active'?'Return to call':'Review call','session-open','small','arrow',`data-id="${e(s.id)}"`)}</div>`).join('')}</section>`:'';}
function sessionDialog(id,sync={}){
  clearTimeout(syncTimer);if(syncSessionId!==id){syncAttempts=0;syncPaused=true;}syncSessionId=id;
  const s=getSession(id);if(!s)return;const l=getLead(s.leadId),m=s.material||{},suggestion=s.suggestion||{};
  const review=s.status==='review'||Boolean(m.transcript),waiting=s.status==='waiting';
  const stored=sessionDrafts.get(id),draft=stored||{outcome:suggestion.outcome||'',notes:suggestion.notes||suggestion.summary||'',nextAction:suggestion.nextAction||'',followUpDate:suggestion.followUpDate||'',meetingAt:suggestion.meetingAt?dateTimeLocal(suggestion.meetingAt):''};
  const status=review?'Review before saving':sync.status==='choose'?'Choose the matching recording':waiting?'Waiting for Wispr':'Your call workspace';
  const options=Object.entries(outcomeNames).map(([key,label])=>`<option value="${key}" ${draft.outcome===key?'selected':''}>${e(label)}</option>`).join('');
  const evidence=Array.isArray(suggestion.evidence)?suggestion.evidence.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('\n'):suggestion.evidence||'';
  const uncertainties=Array.isArray(suggestion.uncertainties)?suggestion.uncertainties.join('\n'):suggestion.uncertainties||'';
  dialog(review?'Make the next step clear.':'Make the call. Keep the context.',`${l?.name||'Lead'} · ${formatTime(s.startedAt)} WAT`,
    `<ol class="call-steps" aria-label="Call progress"><li class="done">1 <span>Call</span></li><li class="${review?'done':'current'}">2 <span>Sync</span></li><li class="${review?'current':''}">3 <span>Confirm</span></li></ol>
    <div class="sync-status ${review?'ready':''}" role="status"><span class="status-dot"></span><div><strong>${e(status)}</strong><p>${e(sync.message||(review?'Transcript saved. Use Draft notes with AI to suggest the outcome and next step, then check the fields and confirm.':waiting?'Wispr can list a recording before the transcript is ready. One automatic retry is available after 30 seconds. After two checks, checking pauses until you choose Check again.':'Start recording in Wispr, then make your WhatsApp call. When both are finished, stop Wispr and sync here.'))}</p></div></div>
    ${!review?`<div class="call-recording-guide"><p><strong>1.</strong> Open Wispr Notetaker and start recording.</p><p><strong>2.</strong> Make your WhatsApp call with the participant’s permission to record.</p><p><strong>3.</strong> End the call and stop Wispr before syncing.</p></div><div class="session-controls">${button(waiting?'Check again':'Finish & sync','session-sync','primary','check',`data-id="${e(id)}"`)}${waiting?button('Pause checking','session-pause','','clock'):''}${button(wisprStatus?.connected?'Wispr settings':'Check Wispr connection','wispr-settings','','settings')}</div>`:''}
    ${sync.candidates?.length?`<div class="candidate-list"><h3 class="section-kicker">Recordings near this call</h3><p class="field-help">Check the time and title. Only choose the conversation with this lead.</p>${sync.candidates.map(c=>`<button type="button" class="candidate" data-action="session-candidate" data-id="${e(id)}" data-meeting="${e(c.id)}"><span><strong>${e(c.title||'Untitled recording')}</strong><small>${e(formatDate(c.start,true))} · ${e(formatTime(c.start))}${c.end?'–'+e(formatTime(c.end)):''} WAT · ${c.has_transcript?'Transcript ready':'Still processing'}</small></span>${icon('chevron')}</button>`).join('')}</div>`:''}
    ${!review?`<details class="sync-fallback"><summary class="details-toggle">Use a Wispr link instead</summary><label class="form-field">Meeting notes link<input type="url" name="syncNotesUrl" placeholder="https://notes.wisprflow.ai/shared/…"></label><p class="field-help">Use this if the recording does not appear or the time does not match.</p>${button('Retrieve this link','session-link','small','','data-id="'+e(id)+'"')}</details><details class="sync-fallback" ${!review||stored?'open':''}><summary class="details-toggle">No answer, or log without a transcript</summary><p class="field-help">You can record the outcome manually. This does not claim a transcript was retrieved.</p>`:''}
    ${review?`<section class="synced-material"><h3 class="section-kicker">Conversation evidence</h3>${m.notesUrl?link(m.notesUrl,'Open original Wispr note'):''}${m.summary?`<p class="sync-summary">${e(m.summary)}</p>`:''}<details><summary class="details-toggle">Read the full transcript</summary><pre class="source-raw" tabindex="0">${e(m.transcript||'No transcript text was returned.')}</pre></details></section>
    <div class="analysis-actions">${button(s.suggestion?'Refresh AI draft':'Draft notes with AI','session-analyze','','note',`data-id="${e(id)}"`)}<span class="field-help">${wisprStatus?.analysisAvailable===false?'AI analysis is not configured. You can review and save manually.':'Uses your Codex account to fill the suggested outcome, call notes, next action and supported dates. Check before saving.'}</span></div>${suggestion.method==='manual_required'?`<div class="notice"><p>${e(uncertainties||'AI analysis is unavailable. Choose the outcome and write the next step yourself.')}</p></div>`:''}${suggestion.summary?`<div class="suggestion"><h3 class="section-kicker">${suggestion.method==='ai'?'AI draft · check against the transcript':'Review notes'}</h3><p>${e(suggestion.summary)}</p>${evidence?`<details><summary class="details-toggle">Evidence behind the draft</summary><pre class="source-raw">${e(evidence)}</pre></details>`:''}${uncertainties?`<p class="field-help">Needs checking: ${e(uncertainties)}</p>`:''}${suggestion.coaching?`<details><summary class="details-toggle">Coaching for your next call</summary><p>${e(suggestion.coaching)}</p></details>`:''}</div>`:''}`:''}
    <label class="form-field">What happened?<select name="outcome" id="session-outcome"><option value="">Choose the outcome</option>${options}</select></label>
    <label class="form-field">Call notes<textarea name="notes" maxlength="10000" placeholder="What they said, the need discussed, and any commitments…">${e(draft.notes)}</textarea></label>
    <div class="form-row"><label class="form-field">Next action<input name="nextAction" value="${e(draft.nextAction)}" maxlength="2000" placeholder="The next concrete step"></label><label class="form-field">Follow-up date<input name="followUpDate" type="date" value="${e(draft.followUpDate)}"></label></div>
    <label class="form-field" id="session-meeting" ${draft.outcome==='meeting_booked'?'':'hidden'}>Agreed meeting / second call · WAT<input name="meetingAt" type="datetime-local" value="${e(draft.meetingAt)}"></label><p class="field-help">Only an agreed meeting with a date and time counts towards your booking goal. After saving, review the calendar details and reminders. No invitation is sent to the prospect.</p>
    ${!review?'</details>':''}<p class="field-help">Your edits stay as a draft in this browser until you confirm the call.</p><div class="session-cancel">${button('Cancel this call session','session-cancel','text danger','','data-id="'+e(id)+'"')}<span class="field-help">Removes it from unfinished calls. No call is counted.</span></div>`,
    async f=>{
      const outcome=f.get('outcome');if(!outcome){modal.querySelector('[data-modal-error]').textContent='Choose what happened before confirming the call.';modal.querySelector('[name="outcome"]').closest('details')?.setAttribute('open','');modal.querySelector('[name="outcome"]').focus();return;}
      let meetingAt;try{meetingAt=outcome==='meeting_booked'?toIso(f.get('meetingAt')):'';}catch{modal.querySelector('[data-modal-error]').textContent='Choose a valid meeting date and time.';return;}
      if(await command('complete_call_session',{sessionId:id,leadId:s.leadId,outcome,notes:f.get('notes'),nextAction:f.get('nextAction'),followUpDate:f.get('followUpDate'),meetingAt},'Call confirmed · lead and daily progress updated')){sessionDrafts.delete(id);saveSessionDrafts();modal.close();selected=s.leadId;tab='calls';mobileDetail=true;render();if(outcome==='meeting_booked'){const saved=getSession(id)?.callId;if(saved)await openCalendar(saved);}}
    });
  modal.classList.add('session-modal');modal.dataset.session=id;if(review)composeCallReview(modal);
  modal.querySelector('.modal-footer button[type="submit"]').textContent='Confirm & save call';modal.querySelector('.modal-footer [data-action="close-modal"]').textContent='Keep for later';
  const form=modal.querySelector('#modal-form');
  const updateRequirements=()=>{const outcome=form.elements.outcome.value;modal.querySelector('#session-meeting').hidden=outcome!=='meeting_booked';form.elements.meetingAt.required=outcome==='meeting_booked';form.elements.followUpDate.required=outcome==='follow_up';modal.querySelector('.modal-footer button[type="submit"]').disabled=!outcome;};
  updateRequirements();form.addEventListener('input',()=>{sessionDrafts.set(id,Object.fromEntries(['outcome','notes','nextAction','followUpDate','meetingAt'].map(k=>[k,form.elements[k].value])));saveSessionDrafts();});form.elements.outcome.addEventListener('change',updateRequirements);
  const heading=modal.querySelector('#modal-title');heading.tabIndex=-1;heading.focus({preventScroll:true});
  if(waiting&&sync.status!=='choose')scheduleSync(id);
}
function scheduleSync(id){
  clearTimeout(syncTimer);
  const info=modal.querySelector('.sync-status p'),pause=modal.querySelector('[data-action="session-pause"]');
  if(syncPaused||syncAttempts>=2){syncPaused=true;if(info)info.textContent=syncAttempts>=2?'Two checks completed. Automatic checking is paused. Your call is kept; choose Check again when Wispr is ready.':'Checking is paused. Your call is kept. Choose Check again when you are ready.';if(pause){pause.disabled=true;pause.textContent='Checking paused';}return;}
  if(info)info.textContent='Transcript not available yet. One automatic retry will run in 30 seconds; you can pause it now.';
  syncTimer=setTimeout(()=>{if(modal.open&&syncSessionId===id&&!syncPaused)syncCall(id,{},true);},30000);
}
async function syncCall(id,extras={},automatic=false){
  if(syncBusy)return;if(!automatic){syncAttempts=0;syncPaused=false;}syncAttempts++;syncBusy=true;clearTimeout(syncTimer);const buttons=modal.querySelectorAll('.session-controls button:not([data-action="session-pause"]),.candidate,.sync-fallback button');buttons.forEach(b=>b.disabled=true);
  const info=modal.querySelector('.sync-status p');if(info)info.textContent='Checking Wispr for this conversation…';
  try{const data=await wisprRequest('sync',{sessionId:id,...extras});if(modal.open&&syncSessionId===id)sessionDialog(id,data.sync||{});}
  catch(err){if(modal.open&&syncSessionId===id){modal.querySelector('[data-modal-error]').textContent=err.message;const status=modal.querySelector('.sync-status p');if(status)status.textContent='Sync paused. Your call is kept. Check the connection or try again.';}toast(err.message,true);}
  finally{syncBusy=false;buttons.forEach(b=>b.disabled=false);}
}
function connectionMarkup(){return `<section class="wispr-settings" aria-labelledby="wispr-heading"><div class="connection-heading"><h3 id="wispr-heading" class="section-kicker">Wispr · call intelligence</h3><span class="connection-pill" data-wispr-pill>Checking connection…</span></div><p class="field-help">Record in Wispr, then retrieve the transcript into the selected lead. Wispr stores and processes its notes in its own service; the desk saves the retrieved copy on this computer.</p><div data-wispr-state role="status"></div><div class="session-controls">${button('Connect Wispr','wispr-connect','','external')}${button('Refresh connection','wispr-status','small')}${button('Disconnect','wispr-disconnect','small','','hidden')}</div><details class="sync-fallback"><summary class="details-toggle">Test a transcript without changing a lead</summary><label class="form-field">Wispr shared notes link<input type="url" name="previewNotesUrl" placeholder="https://notes.wisprflow.ai/shared/…"></label><p class="field-help">This preview does not create a call or change your daily totals.</p>${button('Retrieve preview','wispr-preview','small','note')}<div data-wispr-preview role="status"></div></details></section>`;}
async function refreshWisprStatus(){
  const target=modal.querySelector('[data-wispr-state]');if(!target)return;
  try{const status=await wisprRequest('status');wisprStatus=status;if(!target.isConnected)return;
    modal.querySelector('[data-wispr-pill]').textContent=status.connected?'Connected':'Not connected';
    target.innerHTML=`<p class="field-help">${status.connected?'Wispr is connected. You can retrieve meeting notes and transcripts.':'Connect this desk to your Wispr account. The plugin connection in this chat is separate.'}</p>${status.error?`<p class="inline-error">${e(status.error)}</p>`:''}<p class="field-help">AI drafting: ${status.analysisAvailable?'available':'not configured · manual review is available'}.</p>${status.analysisMessage?`<p class="field-help">${e(status.analysisMessage)}</p>`:''}`;
    modal.querySelector('[data-action="wispr-connect"]').hidden=status.connected;modal.querySelector('[data-action="wispr-disconnect"]').hidden=!status.connected;
  }catch(err){if(target.isConnected){modal.querySelector('[data-wispr-pill]').textContent='Unavailable';target.textContent=err.message;}}
}
function openWisprSettings(){modal.close();settingsDialog();modal.querySelector('[data-wispr-state]')?.scrollIntoView({block:'nearest'});}
async function connectWispr(){const btn=modal.querySelector('[data-action="wispr-connect"]');if(btn)btn.disabled=true;try{const data=await wisprRequest('connect',{});const destination=new URL(data.authorizationUrl);if(destination.protocol!=='https:')throw new Error('Wispr returned an invalid authorization address.');const target=modal.querySelector('[data-wispr-state]');target.innerHTML=`<p class="field-help">Finish authorization in Wispr, then return here and refresh the connection.</p><a class="button small" target="_blank" rel="noopener noreferrer" href="${e(destination.href)}">Open Wispr authorization</a>`;window.open(destination.href,'_blank','noopener,noreferrer');}finally{if(btn)btn.disabled=false;}}
async function previewWispr(){const input=modal.querySelector('[name="previewNotesUrl"]'),target=modal.querySelector('[data-wispr-preview]'),btn=modal.querySelector('[data-action="wispr-preview"]');if(!input.value||!input.reportValidity())return;btn.disabled=true;target.textContent='Retrieving this note…';try{const {meeting}=await wisprRequest('preview',{notesUrl:input.value});if(!target.isConnected)return;target.innerHTML=`<div class="preview-result"><h4>${e(meeting.title||'Untitled meeting')}</h4><p class="field-help">Preview only · no lead or call changed</p>${meeting.content||meeting.summary?`<p class="sync-summary">${e(meeting.summary||meeting.content)}</p>`:''}${meeting.transcript?`<details open><summary class="details-toggle">Transcript retrieved</summary><pre class="source-raw" tabindex="0">${e(meeting.transcript)}</pre></details>`:'<p class="field-help">This recording has no transcript available yet. Wait for Wispr to process it and retrieve again.</p>'}</div>`;}catch(err){if(target.isConnected)target.textContent=err.message;}finally{btn.disabled=false;}}
modal.addEventListener('close',()=>{clearTimeout(syncTimer);syncSessionId='';syncAttempts=0;syncPaused=true;delete modal.dataset.session;modal.classList.remove('session-modal','session-review');});
window.addEventListener('focus',()=>{if(modal.open&&modal.querySelector('[data-wispr-state]'))refreshWisprStatus();});
async function act(action,el){const l=getLead(selected);switch(action){
  case 'start-call':{const existing=openSessions().find(s=>s.leadId===l.id);if(existing){sessionDialog(existing.id);break;}if(await command('start_call',{leadId:l.id},'Call session started · record separately in Wispr')){render();const session=openSessions().find(s=>s.leadId===l.id);if(session)sessionDialog(session.id);}break;}
  case 'session-open':selected=getSession(el.dataset.id)?.leadId||selected;sessionDialog(el.dataset.id);break;
  case 'session-sync':await syncCall(el.dataset.id);break;
  case 'session-pause':syncPaused=true;clearTimeout(syncTimer);scheduleSync(syncSessionId);break;
  case 'session-link':{const input=modal.querySelector('[name="syncNotesUrl"]');if(input.value&&input.reportValidity()){await syncCall(el.dataset.id,{notesUrl:input.value});}break;}
  case 'session-candidate':await syncCall(el.dataset.id,{meetingId:el.dataset.meeting});break;
  case 'session-analyze':{el.disabled=true;el.textContent='Drafting notes…';try{await wisprRequest('analyze',{sessionId:el.dataset.id});if(modal.open&&syncSessionId===el.dataset.id){sessionDialog(el.dataset.id);if(sessionDrafts.has(el.dataset.id))toast('AI draft updated above. Your personal edits were kept.');}}finally{el.disabled=false;el.textContent='Draft notes with AI';}break;}
  case 'session-cancel':{const s=getSession(el.dataset.id);if(s&&await command('cancel_call',{sessionId:s.id,leadId:s.leadId},'Call session cancelled · no call counted')){sessionDrafts.delete(s.id);saveSessionDrafts();modal.close();render();}break;}
  case 'wispr-settings':openWisprSettings();break;
  case 'wispr-connect':await connectWispr();break;
  case 'wispr-status':await refreshWisprStatus();break;
  case 'wispr-disconnect':await wisprRequest('disconnect',{});await refreshWisprStatus();break;
  case 'wispr-preview':await previewWispr();break;
  case 'nav':navigate(el.dataset.view);break;
  case 'replay-welcome':playWelcome(app);break;
  case 'toggle-theme':window.BoltAppearance.toggle();break;
  case 'toggle-motion':window.BoltAppearance.toggleMotion();break;
  case 'opening-prayer':await showOpening();break;
  case 'page':bankPage+=Number(el.dataset.step);selected='';mobileDetail=false;render();document.querySelector('.workspace')?.scrollIntoView({block:'start'});break;
  case 'queue':queue=el.dataset.queue;selected='';mobileDetail=false;render();break;
  case 'select':selected=el.dataset.id;mobileDetail=true;tab='research';render();break;
  case 'tab':tab=el.dataset.tab;render();break;
  case 'back-to-list':mobileDetail=false;render();break;
  case 'copy':try{await navigator.clipboard.writeText(el.dataset.value);toast('Phone number copied');}catch{toast('Select the phone number to copy it.',true);}break;
  case 'save-review':{const d=readReview();if(await command('save_review',{leadId:l.id,...d},'Your observations are saved')){clearDraft(l.id);render();}break;}
  case 'approve':{const d=readReview();if(await command('approve',{leadId:l.id,review:d},'Approved by you · added to calling queue')){clearDraft(l.id);render();}break;}
  case 'stage-dialog':stageDialog(el.dataset.stage);break;
  case 'return-review':if(await command('set_stage',{leadId:l.id,stage:'review',reason:''},'Returned to personal review')){tab='verification';render();}break;
  case 'log-call':callDialog();break;
  case 'edit-call':callDialog(el.dataset.id);break;
  case 'call-material':callMaterialDialog(el.dataset.id);break;
  case 'add-note':{const f=document.querySelector('#note-form');if(await command('note',{leadId:l.id,text:f.elements.note.value},'Note saved')){delete noteDrafts[l.id];try{localStorage.setItem('bevamped-note-drafts-v1',JSON.stringify(noteDrafts));}catch{}render();}break;}
  case 'followup':followupDialog();break;
  case 'settings':settingsDialog();break;
  case 'export-menu':exportDialog();break;
  case 'close-modal':modal.close();break;
  case 'restore':restoreDialog();break;
  case 'refresh':await reload();break;
  case 'open-activity-lead':view='bank';selected=el.dataset.id;mobileDetail=true;search='';stageFilter='';cityFilter='';researchFilter='';tab='calls';render();break;
  case 'clear-conflicts':conflictFilter=false;selected='';render();break;
  case 'view-conflicts':navigate('bank');conflictFilter=true;selected='';render();break;
  case 'add-review':if(await command('add_to_day',{leadId:l.id,kind:'review'},'Added to today’s review queue'))render();break;
}}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el){ev.preventDefault();act(el.dataset.action,el).catch(err=>toast(err.message,true));}});
document.addEventListener('keydown',ev=>{const current=ev.target.closest?.('[role="tab"]');if(current&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const tabs=[...current.closest('[role="tablist"]').querySelectorAll('[role="tab"]')],i=tabs.indexOf(current),n=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(i+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tab=tabs[n].dataset.tab;render();document.getElementById('tab-'+tab)?.focus();return;}if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')){ev.preventDefault();if(view!=='bank')navigate('bank');document.querySelector('#lead-search')?.focus();}});
window.addEventListener('beforeunload',ev=>{const note=document.querySelector('#note-form textarea');if(note?.value.trim()){ev.preventDefault();ev.returnValue='';}});
async function start(){if(!enteredDesk){await showOpening();enteredDesk=true;}try{fetch('/api/wispr/status').then(r=>r.ok?r.json():null).then(s=>{if(s)wisprStatus=s;}).catch(()=>{});const r=await fetch('/api/bootstrap');if(!r.ok)throw new Error('Cannot open the lead bank.');boot=await r.json();await loadCalendar();if(!boot.state.days[boot.today]){if(!await command('start_day',{},''))throw new Error('Could not initialise today’s queue.');}render();playWelcome(app);}catch(err){app.innerHTML=`<main class="load-error"><p class="eyebrow">BOLT by BEVAMPED</p><h1>Your data is still on this computer.</h1><p>${e(err.message)}</p><p>Open the launcher, then refresh this page. If a saved file cannot be read, it is preserved rather than replaced.</p><button class="button primary" id="retry">Try again</button></main>`;document.querySelector('#retry').onclick=start;}}
configureCalendarUI({getBoot:()=>boot,modal,dialog,render,toast,openLead:id=>{view='bank';selected=id;mobileDetail=true;search='';stageFilter='';cityFilter='';researchFilter='';tab='calls';render();}});
configureWorkflowUI({getBoot:()=>boot,setBoot:data=>{boot=data;},modal,dialog,render,toast,command,navigate,openLead:id=>{modal.close();view='bank';selected=id;mobileDetail=true;search='';stageFilter='';cityFilter='';groupFilter='';researchFilter='';conflictFilter=false;tab='calls';render();}});
start();
